public static void main(Args _args)
{
    SalesTable          salesTable;
    ARGSalesTable       argSalesTable;       
    RecordInsertList    recordInsertList;
    int recordsInserted;

    recordInsertList = new RecordInsertList(argSalesTable.TableId);
    while select salesTable
    {
        argSalesTable.clear();
        argSalesTable.SalesId = salesTable.SalesId;
        argSalesTable.PlacedBy = SalesTable_Extension::PlacedBy(salesTable);
        argSalesTable.PaymnMethod = SalesTable_Extension::PaymnMethod(salesTable);
        argSalesTable.DlvMode = SalesTable_Extension::DlvMode(salesTable);
        argSalesTable.ShippingCost = SalesTable_Extension::ShippingCost(salesTable);
        argSalesTable.ShippingAddress = SalesTable_Extension::ShippingAddress(salesTable);
        argSalesTable.TotalAmount = SalesTable_Extension::SalesOrderTotal(salesTable);
        argSalesTable.ItemQuantity = SalesTable_Extension::ItemQuantityTotals(salesTable);            
        recordInsertList.add(argSalesTable);
        break;
    }
    recordsInserted = recordInsertList.insertDatabase();
    info(strFmt("Registros de SalesTable agregados a ARGSalesTable: %1",recordsInserted));

}
